@Suppress("UNCHECKED_CAST")
inline fun <reified T : Any> Any.wrapAs(): T? {
    val info = wrapperRegistry.get(T::class.java)
    if (info != null && info.packetClass.isInstance(this)) {
        return info.constructor(this) as T
    }
    return null
}
